def findLatestTime(s: str) -> str:
    result = list(s)

    # Handle HH:MM
    # First character of hour
    if result[0] == '?' and result[1] == '?':
        result[0] = '1'
        result[1] = '1'
    elif result[0] == '?':
        if result[1] == '0' or result[1] == '1':
            result[0] = '1'
        else:
            result[0] = '0'
    elif result[1] == '?':
        if result[0] == '1':
            result[1] = '1'
        else:
            result[1] = '9'

    # Second character of hour (if still '?')
    if result[1] == '?':
        if result[0] == '1':
            result[1] = '1'
        else:
            result[1] = '9'

    # First character of minute
    if result[3] == '?':
        result[3] = '5'

    # Second character of minute
    if result[4] == '?':
        result[4] = '9'

    return ''.join(result)
