    HX, WX = map(int, data[idx].split())
    idx += 1
    X = [list(data[idx + i]) for i in range(HX)]

    # Collect black positions for A and B
    black_A = []
    for i in range(HA):
        for j in range(WA):
            if A[i][j] == '#':
                black_A.append((i, j))

    black_B = []
    for i in range(HB):
        for j in range(WB):
            if B[i][j] == '#':
                black_B.append((i, j))

    black_X = set()
    for i in range(HX):
        for j in range(WX):
            if X[i][j] == '#':
                black_X.add((i, j))

    # Try all placements of A and B relative to X
    for ax in range(-HA+1, HX):
        for ay in range(-WA+1, WX):
            for bx in range(-HB+1, HX):
                for by in range(-WB+1, WX):
                    # Check if all black squares of A and B are inside X
                    ok = True
                    for (i, j) in black_A:
                        ni, nj = i + ax, j + ay
                        if not (0 <= ni < HX and 0 <= nj < WX):
