We can model the uninfected children as a sequence of contiguous segments between the initially infected positions.  
For a segment of length `k`, each child can only be infected from one of the two ends in a certain order, and the number of ways to interleave infections from different segments follows a combinatorial pattern.

Here’s one way to implement the solution:

```python
def num_sequences(n, sick):
    MOD = 10**9 + 7
    fact = [1] * (n + 1)
    inv_fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    segments = []
    prev = -1
    for s in sick:
        if s > prev + 1:
            segments.append(s - prev - 1)
        prev = s
    if prev < n - 1:
        segments.append(n - prev - 1)

    total = sum(segments)
    res = fact[total]
    for length in segments:
        res = res * inv_fact[length] % MOD

    for i, length in enumerate(segments):
        if (i == 0 and sick[0] != 0) or (i == len(segments) - 1 and sick[-1] != n - 1):
            continue
        if length > 0:
            res = res * pow(2, length - 1, MOD) % MOD

    return res
```

