Here’s a solution that uses the Floyd–Warshall algorithm to compute all‑pairs shortest paths, then uses dynamic programming over subsets (Held–Karp style) to find the minimum walk weight that visits all vertices.  

```python
import sys

def solve() -> None:
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    M = int(next(it))

    INF = 10**18
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        w = int(next(it))
        dist[u][v] = min(dist[u][v], w)

    # Floyd-Warshall
    for k in range(N):
        for i in range(N):
            if dist[i][k] == INF:
                continue
            for j in range(N):
                if dist[k][j] == INF:
                    continue
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Check reachability for all vertices
    reachable = [[False] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            reachable[i][j] = (dist[i][j] < INF)

    # DP over subsets
    dp = [[INF] * N for _ in range(1 << N)]
    for i in range(N):
        dp[1 << i][i] = 0

    for mask in range(1 << N):
        for u in range(N):
            if dp[mask][u] == INF:
                continue
            for v in range(N):
                if mask >> v & 1:
                    continue
                if reachable[u][v]:
                    nmask = mask | (1 << v)
                    dp[nmask][v] = min(dp[nmask][v], dp[mask][u] + dist[u][v])

    full_mask = (1 << N) - 1
    ans = INF
    for u in range(N):
        ans = min(ans, dp[full_mask][u])

    if ans >= INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
```

