    from functools import lru_cache

    @lru_cache(None)
    def dp(pos, tight, leading_zero, even_count, odd_count, remainder, digits):
        if pos == len(digits):
            if leading_zero:
                return 0
            return 1 if (even_count == odd_count and remainder == 0) else 0

        limit = digits[pos] if tight else 9
        total = 0
        for d in range(limit + 1):
            new_tight = tight and (d == limit)
            new_leading_zero = leading_zero and (d == 0)
            new_even = even_count
            new_odd = odd_count
            if not new_leading_zero:
                if d % 2 == 0:
                    new_even += 1
                else:
                    new_odd += 1
            new_remainder = (remainder * 10 + d) % k
            total += dp(pos + 1, new_tight, new_leading_zero, new_even, new_odd, new_remainder, digits)
        return total

    def solve(n):
        digits = list(map(int, str(n)))
        return dp(0, True, True, 0, 0, 0, tuple(digits))

    dp.cache_clear()
    return solve(high) - solve(low - 1)
