def longestValidSubstring(word: str, forbidden: list[str]) -> int:
    # Build a trie for forbidden words
    trie = {}
    for f in forbidden:
        node = trie
        for ch in f:
            if ch not in node:
                node[ch] = {}
            node = node[ch]
        node['#'] = True  # mark end of forbidden word

    max_len = 0
    left = 0
    n = len(word)

    for right in range(n):
        # Check substrings ending at `right` for forbidden words
        node = trie
        # Only need to check up to 10 characters back because forbidden[i].length <= 10
        for i in range(right, left - 1, -1):
            ch = word[i]
            if ch not in node:
                break
            node = node[ch]
            if '#' in node:
                left = i + 1
                break
        max_len = max(max_len, right - left + 1)

    return max_len
