def stringIndices(wordsContainer, wordsQuery):
    class TrieNode:
        def __init__(self):
            self.children = {}
            self.best_index = -1
            self.best_length = float('inf')

    root = TrieNode()

    # Insert all words from wordsContainer into the trie (by reversed characters)
    for idx, word in enumerate(wordsContainer):
        node = root
        word_len = len(word)
        # Update root (empty suffix) with best candidate
        if word_len < node.best_length:
            node.best_length = word_len
            node.best_index = idx

        # Insert characters in reverse order (suffix processing)
        for ch in reversed(word):
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            # Update best candidate for this suffix
            if word_len < node.best_length:
                node.best_length = word_len
                node.best_index = idx

    # Process each query
    ans = []
    for query in wordsQuery:
        node = root
        best_idx = node.best_index  # Default to root's best (empty suffix)

        for ch in reversed(query):
            if ch not in node.children:
                break
            node = node.children[ch]
            best_idx = node.best_index  # Update to current suffix's best

        ans.append(best_idx)

    return ans
