from typing import List

def medianOfUniquenessArray(nums: List[int]) -> int:
    n = len(nums)
    total = n * (n + 1) // 2
    target = (total + 1) // 2

    def count_at_most(k: int) -> int:
        if k == 0:
            return 0
        freq = {}
        left = 0
        res = 0
        for right in range(n):
            freq[nums[right]] = freq.get(nums[right], 0) + 1
            while len(freq) > k:
                freq[nums[left]] -= 1
                if freq[nums[left]] == 0:
                    del freq[nums[left]]
                left += 1
            res += right - left + 1
        return res

    lo, hi = 1, len(set(nums))
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most(mid) >= target:
            hi = mid
        else:
            lo = mid + 1
    return lo
