def find_kth_smallest(coins, k):
    import math
    from itertools import combinations

    def count_less_equal(x):
        count = 0
        for i in range(1, len(coins) + 1):
            for comb in combinations(coins, i):
                lcm = comb[0]
                for num in comb[1:]:
                    lcm = lcm * num // math.gcd(lcm, num)
                if i % 2 == 1:
                    count += x // lcm
                else:
                    count -= x // lcm
        return count

    left, right = 1, min(coins) * k
    while left < right:
        mid = (left + right) // 2
        if count_less_equal(mid) >= k:
            right = mid
        else:
            left = mid + 1
    return left
