import sys

input = sys.stdin.read

def solve():
    data = input().split()
    N, Q = int(data[0]), int(data[1])
    S = data[2]

    # We'll maintain an array diff where diff[i] = 1 if S[i] == S[i+1] else 0
    # For a substring to be good, sum of diff in [L, R-1] must be 0.

    diff = [0] * (N - 1)
    for i in range(N - 1):
        if S[i] == S[i + 1]:
            diff[i] = 1

    # Segment tree for diff
    size = 1
    while size < (N - 1):
        size <<= 1
    seg = [0] * (2 * size)
    lazy = [0] * (2 * size)

    for i in range(N - 1):
        seg[size + i] = diff[i]
    for i in range(size - 1, 0, -1):
        seg[i] = seg[i * 2] + seg[i * 2 + 1]

    def apply(node, length):
        seg[node] = length - seg[node]
        if node < size:
            lazy[node] ^= 1

    def push(node, ln, rn):
        if lazy[node]:
            apply(node * 2, ln)
            apply(node * 2 + 1, rn)
            lazy[node] = 0

    def update(node, l, r, ql, qr):
        if ql <= l and r <= qr:
            apply(node, r - l + 1)
            return
        m = (l + r) // 2
        push(node, m - l + 1, r - m)
        if ql <= m:
            update(node * 2, l, m, ql, qr)
        if qr > m:
            update(node * 2 + 1, m + 1, r, ql, qr)
        seg[node] = seg[node * 2] + seg[node * 2 + 1]

    def query(node, l, r, ql, qr):
        if ql > r or qr < l:
            return 0
        if ql <= l and r <= qr:
            return seg[node]
        m = (l + r) // 2
        push(node, m - l + 1, r - m)
        return query(node * 2, l, m, ql, qr) + query(node * 2 + 1, m + 1, r, ql, qr)

    idx = 3
    out = []
    for _ in range(Q):
        t = int(data[idx])
        L = int(data[idx + 1]) - 1
        R = int(data[idx + 2]) - 1
        idx += 3
        if t == 1:
            # Flip affects diff at L-1 and R
            if L > 0:
                update(1, 0, size - 1, L - 1, L - 1)
            if R < N - 1:
                update(1, 0, size - 1, R, R)
        else:
            if L == R:
                out.append("Yes")
            else:
                s = query(1, 0, size - 1, L, R - 1)
                out.append("Yes" if s == 0 else "No")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
