        dp0[1][0] = 1
    if one > 0:
        dp1[0][1] = 1

    # Fill DP table
    for i in range(zero + 1):
        for j in range(one + 1):
            if i == 0 and j == 0:
                continue

            # Try to add a 0 at the end
            # We can add 0 if we have zeros left
            # The previous sequence could end with 0 or 1
            # But if it ends with 0, we need to ensure we don't exceed limit consecutive 0s
            for k in range(1, min(limit, i) + 1):
                if i - k >= 0:
                    # Previous sequence ended with 1
                    if i - k >= 0 and j >= 0:
                        dp0[i][j] = (dp0[i][j] + dp1[i - k][j]) % MOD
                    # If k == i and j == 0, it's a sequence of all zeros
                    if k == i and j == 0:
                        dp0[i][j] = (dp0[i][j] + 1) % MOD

            # Try to add a 1 at the end
            for k in range(1, min(limit, j) + 1):
                if j - k >= 0:
                    # Previous sequence ended with 0
                    if i >= 0 and j - k >= 0:
                        dp1[i][j] = (dp1[i][j] + dp0[i][j - k]) % MOD
                    # If k == j and i == 0, it's a sequence of all ones
                    if k == j and i == 0:
                        dp1[i][j] = (dp1[i][j] + 1) % MOD

    return (dp0[zero][one] + dp1[zero][one]) % MOD
