def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    bits = [0] * 32
    for num in nums:
        for b in range(32):
            if num >> b & 1:
                bits[b] += 1

    final_nums = [0] * len(nums)
    for b in range(32):
        for i in range(bits[b]):
            final_nums[i] |= (1 << b)

    final_nums.sort(reverse=True)
    ans = sum(x * x for x in final_nums[:k]) % MOD
    return ans
