import sys

def solve():
    input = sys.stdin.readline
    H, W, T = map(int, input().split())
    grid = [list(input().strip()) for _ in range(H)]

    # Find start, goal, and candy positions
    candies = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.append((i, j))

    points = [start] + candies + [goal]
    n = len(points)  # start=0, candies=1..C, goal=C+1
    C = len(candies)

    # BFS from each point of interest
    def bfs(sx, sy):
        dist = [[-1] * W for _ in range(H)]
        dist[sx][sy] = 0
        q = deque([(sx, sy)])
        while q:
            x, y = q.popleft()
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#':
                    if dist[nx][ny] == -1:
                        dist[nx][ny] = dist[x][y] + 1
                        q.append((nx, ny))
        return dist

    # Precompute distances between all points of interest
    dists = []
    for p in points:
        dists.append(bfs(p[0], p[1]))

    INF = 10**9
    # dp[mask][i] = min moves to visit candies in mask, ending at i (i=0..C, where 0 is start, C+1 is goal)
    dp = [[INF] * (C+1) for _ in range(1 << C)]
    for i in range(C):
        d = dists[0][candies[i][0]][candies[i][1]]
        if d != -1:
            dp[1 << i][i] = d

