                continue
            for j in range(C):
                if not (mask >> j) & 1:
                    d = dists[i+1][candies[j][0]][candies[j][1]]
                    if d != -1:
                        nmask = mask | (1 << j)
                        dp[nmask][j] = min(dp[nmask][j], dp[mask][i] + d)

    # Check if goal is reachable
    start_to_goal = dists[0][goal[0]][goal[1]]
    if start_to_goal == -1 or start_to_goal > T:
        print(-1)
        return

    max_candies = 0
    # Check all subsets of candies
    for mask in range(1 << C):
        for i in range(C):
            if dp[mask][i] == INF:
                continue
            d_to_goal = dists[i+1][goal[0]][goal[1]]
            if d_to_goal != -1 and dp[mask][i] + d_to_goal <= T:
                max_candies = max(max_candies, bin(mask).count("1"))

