from collections import Counter

def solve():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:]))

    # Precompute smallest prime factor for numbers up to 200000
    MAX_A = 200000
    spf = list(range(MAX_A + 1))
    for i in range(2, int(MAX_A**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX_A + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def reduce_to_squarefree(x):
        if x == 0:
            return -1  # special marker for zero
        res = 1
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt += 1
            if cnt % 2 == 1:
                res *= p
        return res

    reduced = [reduce_to_squarefree(a) for a in A]
    cnt = Counter(reduced)

    ans = 0
    zero_count = cnt.get(-1, 0)
    # Pairs with zero
    if zero_count > 0:
        ans += zero_count * (N - zero_count) + zero_count * (zero_count - 1) // 2

    # Pairs among same squarefree numbers (excluding zero)
    for k, v in cnt.items():
        if k != -1 and v > 1:
            ans += v * (v - 1) // 2

    print(ans)

