from collections import defaultdict

def countCompleteSubstrings(word: str, k: int) -> int:
    n = len(word)

    def check_adjacent(sub: str) -> bool:
        for i in range(len(sub) - 1):
            if abs(ord(sub[i]) - ord(sub[i + 1])) > 2:
                return False
        return True

    def count_for_unique(unique_count: int) -> int:
        window_size = unique_count * k
        if window_size > n:
            return 0

        freq = defaultdict(int)
        left = 0
        count = 0

        for right in range(n):
            freq[word[right]] += 1

            if right - left + 1 > window_size:
                freq[word[left]] -= 1
                if freq[word[left]] == 0:
                    del freq[word[left]]
                left += 1

            if right - left + 1 == window_size:
                if all(v == k for v in freq.values()) and len(freq) == unique_count:
                    if check_adjacent(word[left:right + 1]):
                        count += 1

        return count

    result = 0
    max_unique = min(26, n // k)
    for u in range(1, max_unique + 1):
        result += count_for_unique(u)

    return result
