from typing import List
import math

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x: int, y: int) -> None:
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            if self.rank[root_x] < self.rank[root_y]:
                self.parent[root_x] = root_y
            elif self.rank[root_x] > self.rank[root_y]:
                self.parent[root_y] = root_x
            else:
                self.parent[root_y] = root_x
                self.rank[root_x] += 1

def can_traverse_all_pairs(nums: List[int]) -> bool:
    n = len(nums)
    if n <= 1:
        return True

    max_val = max(nums)

    # smallest prime factor sieve
    spf = list(range(max_val + 1))
    for i in range(2, int(math.isqrt(max_val)) + 1):
        if spf[i] == i:
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    uf = UnionFind(n)

    # Map from prime factor to first index that has this factor
    prime_to_index = {}

    for idx, num in enumerate(nums):
        # find all unique prime factors of num
        factors = set()
        while num > 1:
            p = spf[num]
            factors.add(p)
            while num % p == 0:
                num //= p

        for p in factors:
            if p in prime_to_index:
                uf.union(idx, prime_to_index[p])
            else:
                prime_to_index[p] = idx

    # Check if all nodes belong to the same connected component
    root = uf.find(0)
    for i in range(1, n):
        if uf.find(i) != root:
            return False
    return True
