def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute divisibility matrix
    div = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    div[i][j] = True

    # dp[mask][last] = number of ways to form a special permutation 
    # using elements in mask, ending with element at index 'last'
    dp = [[0] * n for _ in range(1 << n)]

    # Base case: permutations of length 1
    for i in range(n):
        dp[1 << i][i] = 1

    # Iterate over all masks
    for mask in range(1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            if dp[mask][last] == 0:
                continue
            # Try to add a new element
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                if div[last][nxt]:
                    new_mask = mask | (1 << nxt)
                    dp[new_mask][nxt] = (dp[new_mask][nxt] + dp[mask][last]) % MOD

    # Sum all full permutations
    full_mask = (1 << n) - 1
    result = 0
    for last in range(n):
        result = (result + dp[full_mask][last]) % MOD

    return result
