    C = input_data[2]

    # Each row and column must have exactly one A, B, C
    grid = [['.' for _ in range(N)] for _ in range(N)]

    row_used = [[False, False, False] for _ in range(N)]  # A, B, C
    col_used = [[False, False, False] for _ in range(N)]

    def char_to_idx(ch):
        return ord(ch) - ord('A')

    def check_leftmost(row):
        for j in range(N):
            if grid[row][j] != '.':
                return grid[row][j] == R[row]
        return False

    def check_topmost(col):
        for i in range(N):
            if grid[i][col] != '.':
                return grid[i][col] == C[col]
        return False

    def backtrack(cell):
        if cell == N * N:
            # Final check
            for i in range(N):
                if not check_leftmost(i):
                    return False
            for j in range(N):
                if not check_topmost(j):
                    return False
            return True

        r, c = divmod(cell, N)

        # Try placing A, B, C or empty
        for ch in ['.', 'A', 'B', 'C']:
            if ch == '.':
                if backtrack(cell + 1):
                    return True
            else:
                idx = char_to_idx(ch)
                if not row_used[r][idx] and not col_used[c][idx]:
                    # Place character
                    grid[r][c] = ch
                    row_used[r][idx] = True
                    col_used[c][idx] = True

                    # Early pruning: check leftmost/topmost only if this is the first char in row/col
                    valid = True
